const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brands=['KUGOO','ELTRECO','MINAKO'];
let activeModel=null,activeBrand='Все';
let activeType='Все';
const comparison=new Set();
function notify(message){const t=document.querySelector('#toast');t.textContent=message;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3000);}
function renderCatalog(){const query=document.querySelector('#search').value.toLowerCase().trim(),sort=document.querySelector('#sort').value;const minRange=Number(document.querySelector('#range-filter').value),maxPrice=Number(document.querySelector('#budget-filter').value);let models=MODELS.filter(m=>(activeBrand==='Все'||m.brand===activeBrand)&&(activeType==='Все'||m.type===activeType)&&m.range>=minRange&&m.price<=maxPrice&&(`${m.brand} ${m.name} ${m.type}`).toLowerCase().includes(query));if(sort==='price')models.sort((a,b)=>a.price-b.price);if(sort==='range')models.sort((a,b)=>b.range-a.range);document.querySelector('#grid').innerHTML=models.length?models.map(m=>`<article class="card"><a class="card-photo" href="panel.html?model=${m.id}"><img src="assets/${m.id}.jpg" alt="${m.brand} ${m.name}" loading="lazy"></a><div class="card-body"><div class="card-brand">${m.brand}</div><h3><a href="panel.html?model=${m.id}">${m.name}</a></h3><div class="card-specs"><div>до ${m.range} км<small>запас хода</small></div><div>${m.power} Вт<small>мощность</small></div></div><div class="card-bottom"><div class="card-price"><strong>${money(m.price)}</strong><small>Цена поставщика</small></div><a class="card-arrow" href="panel.html?model=${m.id}">Подробнее</a><button class="compare-toggle" data-compare="${m.id}" aria-label="Сравнить ${m.brand} ${m.name}" aria-pressed="${comparison.has(m.id)}">${comparison.has(m.id)?'✓':'≋'}</button></div></div></article>`).join(''):'<p>Нет моделей с такими параметрами. Измените фильтры или сбросьте их.</p>';document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{toggleComparison(b.dataset.compare);renderCatalog();});}
function toggleComparison(id){if(!MODELS.some(m=>m.id===id))throw Error('Модель не найдена');if(comparison.has(id))comparison.delete(id);else if(comparison.size<3)comparison.add(id);else {notify('Можно сравнить до трёх моделей');return;}const count=document.querySelector('#compare-count');if(count)count.textContent=comparison.size;notify(comparison.has(id)?'Модель добавлена к сравнению':'Модель убрана из сравнения');}
function openComparison(){const models=MODELS.filter(m=>comparison.has(m.id));const content=document.querySelector('#compare-content');content.innerHTML=models.length?'<table><thead><tr><th>Параметр</th>'+models.map(m=>`<th>${m.brand} ${m.name}</th>`).join('')+'</tr></thead><tbody><tr><th>Модель</th>'+models.map(m=>`<td><img src="assets/${m.id}.jpg" alt="${m.brand} ${m.name}"></td>`).join('')+'</tr>'+[['Цена поставщика',m=>money(m.price)],['Запас хода',m=>`до ${m.range} км`],['Мощность',m=>`${m.power} Вт`],['Батарея',m=>m.battery],['Вес',m=>`${m.weight} кг`],['Колёса',m=>m.wheels],['Тормоза',m=>m.brakes],['Нагрузка',m=>`до ${m.load} кг`],['Источник',m=>`<a href="${m.source}" target="_blank" rel="noopener">${m.supplier}</a>`]].map(([label,fn])=>'<tr><th>'+label+'</th>'+models.map(m=>'<td>'+fn(m)+'</td>').join('')+'</tr>').join('')+'</tbody></table><p class="note">Цены поставщиков — ориентир. Итоговую цену и доставку необходимо подтвердить.</p>':'<p>Добавьте модели кнопкой сравнения в каталоге.</p>';document.querySelector('#compare-dialog').showModal();}
function catalogBrand(b){if(!['Все',...brands].includes(b))throw new Error('Неизвестный производитель');activeBrand=b;document.querySelectorAll('#brands button').forEach(x=>{x.classList.toggle('active',x.dataset.brand===b);x.setAttribute('aria-pressed',String(x.dataset.brand===b));});renderCatalog();return {brand:b,count:document.querySelectorAll('.card').length};}
function selectModel(id){const m=MODELS.find(m=>m.id===id);if(!m)throw new Error('Модель не найдена');activeModel=m;document.querySelector('#panel-brands').innerHTML=brands.map(b=>`<button data-brand="${b}" class="${m.brand===b?'active':''}" aria-pressed="${m.brand===b}">${b}</button>`).join('');document.querySelectorAll('#panel-brands button').forEach(b=>b.onclick=()=>selectModel(MODELS.find(x=>x.brand===b.dataset.brand).id));document.querySelector('#model-list').innerHTML=MODELS.filter(x=>x.brand===m.brand).map(x=>`<button data-model="${x.id}" class="${x.id===m.id?'active':''}" aria-pressed="${x.id===m.id}">${x.name}${x.id===m.id?'<span>↗</span>':''}</button>`).join('');document.querySelectorAll('#model-list button').forEach(b=>b.onclick=()=>selectModel(b.dataset.model));for(const [id,text] of Object.entries({'kind':m.type,'model-brand':m.brand,'model-name':m.name,'model-desc':m.desc,'price':money(m.price),'supplier':m.supplier,'availability':m.availability}))document.getElementById(id).textContent=text;const img=document.querySelector('#model-image');img.src=`assets/${m.id}.jpg`;img.alt=`${m.brand} ${m.name}`;document.querySelector('#metrics').innerHTML=`<div><strong>до ${m.range} <small>км · запас хода</small></strong></div><div><strong>${m.power} <small>Вт · мощность</small></strong></div><div><strong>${m.weight} <small>кг · вес</small></strong></div>`;document.querySelector('#specs').innerHTML='<dl>'+[['Батарея',m.battery],['Колёса',m.wheels],['Тормоза',m.brakes],['Нагрузка',`до ${m.load} кг`]].map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')+'</dl><p class="note">'+esc(m.availability)+'. Это данные поставщика, а не склад ProfiSport.</p>';document.querySelector('#source').href=m.source;document.querySelector('#shipping-source').href=m.brand==='KUGOO'?'https://www.kugoo-russia.ru/delivery':m.brand==='MINAKO'?'https://elektro-vostok.ru/':'https://eltreco.ru/';history.replaceState(null,'',`?model=${m.id}`);const c=document.querySelector('#component-detail');if(c)c.hidden=true;document.querySelectorAll('[data-component]').forEach(b=>b.classList.remove('active'));return {id:m.id,brand:m.brand,name:m.name,supplierPrice:m.price,delivery:'requires_confirmation'};}
function setTab(tab){if(!['specs','delivery'].includes(tab))throw new Error('Неизвестная вкладка');document.querySelector('#specs').hidden=tab!=='specs';document.querySelector('#delivery').hidden=tab!=='delivery';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));}
if(document.querySelector('#grid')){document.querySelector('#brands').innerHTML=['Все',...brands].map(b=>`<button data-brand="${b}" aria-pressed="${b==='Все'}" class="${b==='Все'?'active':''}">${b}</button>`).join('');document.querySelectorAll('#brands button').forEach(b=>b.onclick=()=>catalogBrand(b.dataset.brand));document.querySelector('#search').oninput=renderCatalog;document.querySelector('#sort').onchange=renderCatalog;renderCatalog();}
if(document.querySelector('#model-list')){selectModel(new URLSearchParams(location.search).get('model')&&MODELS.some(x=>x.id===new URLSearchParams(location.search).get('model'))?new URLSearchParams(location.search).get('model'):MODELS[0].id);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));const dialog=document.querySelector('#photo-dialog');document.querySelector('#zoom').onclick=()=>{const img=document.querySelector('#large-photo');img.src=`assets/${activeModel.id}.jpg`;img.alt=`${activeModel.brand} ${activeModel.name}`;dialog.showModal();};document.querySelector('#close-photo').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close();};document.querySelector('#save').onclick=()=>{const m=activeModel;const text=`ProfiSport — подбор электротранспорта\n${m.brand} ${m.name}\nЦена в каталоге поставщика: ${money(m.price)}\nПоставщик: ${m.supplier}\nЗапас хода: до ${m.range} км\nМощность: ${m.power} Вт\nБатарея: ${m.battery}\nВес: ${m.weight} кг\nНаличие: ${m.availability}\nДоставка в Оренбург: срок и стоимость требуют расчёта.\nИтоговая цена ProfiSport требует подтверждения.\nИсточник: ${m.source}\nДанные проверены 05.10.2026\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`ProfiSport-${m.brand}-${m.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);const t=document.querySelector('#toast');t.textContent='Подбор сохранён в файл';t.style.display='block';setTimeout(()=>t.style.display='none',3000);};}
if(document.modelContext?.registerTool){const controller=new AbortController();const tool=document.querySelector('#model-list')?{name:'select_transport_model',description:'Выбрать модель в клиентской панели ProfiSport. Не отправляет заявку.',inputSchema:{type:'object',properties:{modelId:{type:'string',enum:MODELS.map(x=>x.id)}},required:['modelId'],additionalProperties:false},execute:input=>{if(!input||typeof input.modelId!=='string')throw new Error('Требуется modelId');return selectModel(input.modelId);}}:{name:'filter_transport_catalog',description:'Выбрать производителя в каталоге ProfiSport.',inputSchema:{type:'object',properties:{brand:{type:'string',enum:['Все',...brands]}},required:['brand'],additionalProperties:false},execute:input=>{if(!input||typeof input.brand!=='string')throw new Error('Требуется brand');return catalogBrand(input.brand);}};try{Promise.resolve(document.modelContext.registerTool({...tool,annotations:{readOnlyHint:false,untrustedContentHint:false}},{signal:controller.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}

if(document.querySelector('#grid')){
 document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{activeType=b.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x.dataset.type===activeType));renderCatalog();});
 document.querySelectorAll('[data-category]').forEach(a=>a.onclick=()=>{activeType=a.dataset.category;document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x.dataset.type===activeType));renderCatalog();});
 document.querySelector('#range-filter').oninput=e=>{document.querySelector('#range-value').textContent=e.target.value+' км';renderCatalog();};
 document.querySelector('#budget-filter').oninput=e=>{document.querySelector('#budget-value').textContent=money(Number(e.target.value));renderCatalog();};
 document.querySelector('#reset-filters').onclick=()=>{activeType='Все';document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x.dataset.type==='Все'));document.querySelector('#search').value='';document.querySelector('#sort').value='default';document.querySelector('#range-filter').value=0;document.querySelector('#budget-filter').value=100000;document.querySelector('#range-value').textContent='0 км';document.querySelector('#budget-value').textContent=money(100000);catalogBrand('Все');};
 document.querySelector('#compare-open').onclick=openComparison;
}
if(document.querySelector('#model-list')){
 document.querySelectorAll('[data-component]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-component]').forEach(x=>x.classList.toggle('active',x===b));const values={battery:['Аккумулятор',activeModel.battery],brakes:['Тормоза',activeModel.brakes],wheels:['Колёса',activeModel.wheels]};const [label,value]=values[b.dataset.component];const d=document.querySelector('#component-detail');d.textContent=label+': '+value;d.hidden=false;});
 document.querySelector('#panel-compare').onclick=()=>{if(!comparison.has(activeModel.id)){if(comparison.size>=3){notify('Можно сравнить до трёх моделей');return;}comparison.add(activeModel.id);}openComparison();};
 document.querySelector('#compare-content').addEventListener('click',()=>{});
}
const information={delivery:'<h2>Доставка и оплата</h2><p>Доставка в Оренбург рассчитывается для выбранной модели по адресу и габаритам. Точные сроки, стоимость перевозки и итоговая цена ProfiSport требуют подтверждения.</p><p>Оплату и условия получения согласуйте с магазином до заказа.</p>',service:'<h2>Подбор и сервис</h2><p>Для обслуживания или подбора техники обратитесь в магазин ProfiSport. Укажите модель и задачу: повседневные поездки, дальние маршруты или ремонт.</p><p>Адрес: Оренбург, проспект Победы, 79.</p>',contacts:'<h2>Наши магазины</h2><p>Профи Спорт · Оренбург</p><a href="https://yandex.ru/maps/?text=Оренбург%20проспект%20Победы%2079" target="_blank" rel="noopener">Проспект Победы, 79</a><a href="https://yandex.ru/maps/?text=Оренбург%20проспект%20Победы%20118%20строение%202" target="_blank" rel="noopener">Проспект Победы, 118, строение 2</a><p>Наличие выбранного электротранспорта в магазине уточняется отдельно.</p>'};
document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>{document.querySelector('#info-content').innerHTML=information[b.dataset.info];document.querySelector('#info-dialog').showModal();});
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close();}));
